MC_PART1 = {
    "MC0001": r"Chào [BUF01][BUF05] nhé!\nTôi là [BUF02] đây.\pLúc nãy tôi thấy một con [BUF03]\nnhưng mà bắt hụt mất rồi.\pTiếc thật đấy, suýt nữa là được rồi!\nThôi, hẹn gặp lại cậu sau nhé!",
    "MC0002": r"Chào [BUF01][BUF05].\nTôi là [BUF02] đây.\pCách đây một lúc tôi có thử bắt\nmột bé [BUF03] rất dễ thương.\pNhưng nó lại chạy mất tiêu.\nThất vọng ghê luôn á!\pThôi nhé, tạm biệt!",
    "MC0003": r"Chào [BUF01] nhé!\nTôi là [BUF02] đây.\pTôi vừa thử ném bóng bắt con [BUF03]\nnhưng nó đã chạy biến mất.\pSuýt chút nữa là tóm được rồi chứ!\pMất cả vui cả ngày luôn…\nThôi được rồi, hẹn gặp lại nhé!",
    "MC0004": r"Chào [BUF01][BUF05].\n[BUF02] đây.\pCậu biết loài Pokémon [BUF03] chứ?\nTôi suýt bắt được một con đấy.\pVừa mới lúc nãy thôi.\nCứ ngỡ là tóm được rồi mà nó lại trốn thoát.\pLần tới mà gặp lại, nhất định\ntôi sẽ bắt bằng được cho xem.\pThôi nhé, hẹn gặp lại sau.",
    "MC0005": r"Chào [BUF01][BUF05] nha!\nTôi là [BUF02] đây.\lDạo này cậu có bắt được bé Pokémon nào không?\pLúc nãy tôi suýt nữa thì tóm gọn\nđược một con, thế mà lại để tuột mất.\pThế nhé, bảo trọng nha!",
    "MC0006": r"Chào [BUF01][BUF05].\n[BUF02] đây.\lDạo này cậu có bắt được Pokémon nào không?\pHôm nọ tôi suýt tóm được một con đấy.\nThế nhưng chẳng hiểu sao nó lại né được.\pCậu giữ gìn sức khỏe nhé.",
    "MC0007": r"…Ủa, [BUF01][BUF05] hả?\nTôi là [BUF02] đây.\pÔi, chờ đã! Khoan đã nào!\nTôi bắt được con [BUF03] này rồi…\pÁaaa! Nó giật ra chạy mất rồi!\nKhông chỉ suýt soát thôi đâu, tiếc đứt ruột!",
    "MC0008": r"Ồ, [BUF01][BUF05], cậu khỏe không?\nTôi là [BUF02] đây.\pDạo này cậu thu phục Pokémon\ncó thuận lợi không?\pCách đây một lúc tôi suýt tóm được mục tiêu,\nnhưng nó lại thoát ra mất.\pTôi phải nỗ lực hơn mới được!\nHẹn gặp lại cậu nhé!",
    "MC0009": r"Ồ, [BUF01][BUF05], chào cậu nhé!\nTôi là [BUF02] đây!\pThế nào rồi? Cậu đã thu phục thêm\nđược nhiều Pokémon chưa?\pCòn tôi thì xui xẻo đủ đường!\nCon nào con nấy đều chạy trốn khỏi tôi cả!\pHẹn gặp lại nhé!",
    "MC0010": r"Ồ, [BUF01][BUF05], chào cậu…\nTôi là [BUF02] đây.\pNghe này, suýt trong đường tơ kẽ tóc nữa\nlà tôi bắt được con [BUF03] này rồi…\pThế nhưng nó đã nhanh chân lẩn mất…\pTôi cần phải cố gắng hơn nữa.\nHẹn gặp lại sau nhé.",
    "MC0011": r"A, [BUF01][BUF05].\nTôi là [BUF02] đây.\lMọi chuyện của cậu thế nào rồi?\pLúc nãy tôi có thử bắt một con [BUF03] hoang dã,\nnhưng nó đã kịp tẩu thoát.\pTôi thấy nản lòng quá…",
    "MC0012": r"Chào [BUF01][BUF05].\nTôi là [BUF02] đây.\lCậu vẫn đang đi bắt Pokémon chứ?\pBản thân tôi cũng đang cố gắng bắt chúng,\nnhưng chẳng hề dễ dàng chút nào.\pĐạo Pokémon quả thật thâm sâu!",
    "MC0013": r"A, chào [BUF01][BUF05] nhé!\nTôi là [BUF02] đây!\lCậu có đang đi bắt Pokémon không?\pTôi cũng đang tự mình đi thu phục chúng,\nnhưng mà chẳng mấy thành công.\pĐạo Pokémon quả thật thâm sâu!",
    "MC0014": r"Ôi, chào [BUF01][BUF05], cậu khỏe không?\nTôi là [BUF02] đây.\pVừa mới đây thôi, tôi đã thử bắt\nmột bé [BUF03] rất đáng yêu.\pThế mà nó lại trốn mất!\nÔi, cậu không tưởng tượng được tôi hụt hẫng thế nào đâu!\pBai bai nhé!",
    "MC0015": r"Này, [BUF01]!\n[BUF02] đây nè!\pTôi đang tính đi tìm bắt\nvài con Pokémon xem sao.\pThế nhưng tìm mãi chẳng thấy con nào cả.\nThật là nan giải hết sức!\pTôi bó tay chấm com luôn rồi!\nHẹn gặp lại sau nha!",
    "MC0016": r"Chào [BUF01][BUF05] nhé!\nTôi là [BUF02] đây.\pTôi vừa thử đấu với một Huấn luyện viên khác,\nnhưng mà thua mất rồi.\pThật sự thất vọng ghê luôn á.\nThôi, hẹn gặp lại cậu sau nhé!",
    "MC0017": r"Chào [BUF01][BUF05].\nTôi là [BUF02] đây.\pSau trận đấu với cậu, tôi đã thách đấu\nmột người khác.\pSuýt thắng rồi mà cuối cùng lại để thua.\nHaizz, đành chịu thôi!",
    "MC0018": r"Chào [BUF01] nhé!\nTôi là [BUF02] đây.\pTôi vừa bị đánh cho tơi bời trong trận đấu.\pChắc là tôi phải huấn luyện đội hình của mình\nthêm nữa mới được!",
    "MC0019": r"Chào [BUF01].\n[BUF02] đây.\pHôm qua tôi vừa thử thêm một trận đấu nữa,\nnhưng không thể giành được chiến thắng.\pĐội của tôi cần rèn luyện thêm nữa.\nThôi nhé, hẹn gặp lại sau.",
    "MC0020": r"Chào [BUF01] nha!\nTôi là [BUF02] đây.\pMọi chuyện của cậu thế nào rồi?\pTôi vẫn miệt mài thi đấu,\nnhưng chẳng mấy khi thắng nổi.\pMãi mà chưa lấy lại được phong độ.\nThế nhé, bảo trọng nha!",
    "MC0021": r"Chào [BUF01].\n[BUF02] đây.\pDạo này cậu thế nào rồi?\pGần đây tôi chiến đấu rất hăng say,\nnhưng kết quả chẳng mấy khả quan.\pMãi mà không vào guồng được.\nCậu nhớ giữ gìn sức khỏe nhé.",
    "MC0022": r"[BUF02] đây.\nDạo này cậu thế nào rồi?\pHôm qua tôi vừa thua một trận đấu,\nvà chuyện đó cứ lởn vởn mãi trong đầu tôi.\pTôi phải vạch ra một kế hoạch mới được…\nHẹn gặp lại.",
    "MC0023": r"Ồ, [BUF01][BUF05], cậu khỏe không?\nTôi là [BUF02] đây.\pPokémon của cậu dạo này thế nào?\nHôm nọ tôi vừa thua một trận xong.\pTôi cần phải cố gắng hơn nữa!\nHẹn gặp lại cậu nhé!",
    "MC0024": r"Ồ, [BUF01][BUF05], chào cậu nhé!\nTôi là [BUF02] đây!\pNghe này, nghe này, cậu phải nghe\nchuyện này mới được!\pLúc nãy tôi vừa có một trận đấu Pokémon,\nthế mà lại thua ở đúng giây cuối cùng.\pÔi, tức anh ách luôn á!",
    "MC0025": r"Ồ, [BUF01][BUF05], chào cậu…\nTôi là [BUF02] đây.\pCách đây một lúc tôi vừa tham gia một trận đấu.\nThế nhưng tôi lại thua rồi.\pTôi cần huấn luyện thêm cho Pokémon của mình.\nHẹn gặp lại sau nhé.",
    "MC0026": r"A, [BUF01][BUF05].\nTôi là [BUF02] đây.\lPokémon của cậu thế nào rồi?\pTôi lại vừa để thua thêm một trận nữa rồi.\pThôi nhé, hẹn gặp lại!",
    "MC0027": r"Chào [BUF01][BUF05].\nTôi là [BUF02] đây.\lCậu vẫn đang nỗ lực chiến đấu chứ?\pCòn tôi vừa mới thua trận gần đây, nên đang\nhuấn luyện lại toàn bộ đội hình của mình.\pHẹn gặp lại cậu sau nhé.",
    "MC0028": r"A, chào [BUF01][BUF05] nhé!\nTôi là [BUF02] đây!\pMong là cậu vẫn luôn khỏe mạnh.\pNgay trước cuộc gọi này tôi vừa có một trận đấu xong.\p[BUF01][BUF05], hãy luôn tràn đầy năng lượng như tôi nhé.\nHẹn gặp lại!",
    "MC0029": r"Ôi, chào [BUF01][BUF05].\nTôi là [BUF02] đây.\pCậu vẫn khỏe chứ?\pThỉnh thoảng cậu cũng nên về thăm nhà\nmột chuyến đấy nhé.\pBai bai!",
    "MC0030": r"Chào [BUF01][BUF05] nhé!\nTôi là [BUF02] đây!\pLúc nãy tôi vừa đấu với một Huấn luyện viên khác.\nTôi thắng rồi! Thắng rồi nè!\pBé [BUF03] của tôi đã chiến đấu hết mình luôn.\nTuyệt vời ông mặt trời!",
    "MC0031": r"Chào [BUF01][BUF05]!\nTôi là [BUF02] đây!\pHôm qua tôi vừa có một trận đấu\nvà tôi đã thắng đó! Thật là tuyệt vời!",
    "MC0032": r"Chào [BUF01] nhé!\nTôi là [BUF02] đây nè!\lDạo này cậu chiến đấu thế nào rồi?\pCòn tôi, hôm nọ vừa thi đấu một trận,\nvà [BUF03] của tôi đã tỏa sáng rực rỡ!\pLần tới khi so tài với cậu,\n[BUF01], người thua cuộc chắc chắn không phải tôi đâu!",
    "MC0033": r"Chào [BUF01].\n[BUF02] đây.\pLúc nãy tôi vừa có một trận đấu.\nTuy suýt soát nhưng tôi cũng đã giành chiến thắng.\pBé [BUF03] của tôi đã có\nmột màn trình diễn đầy cảm hứng.",
    "MC0034": r"Chào [BUF01][BUF05] nha!\nTôi là [BUF02] đây.\pMọi chuyện của cậu thế nào rồi?\nCó đấu nhiều không?\pVừa rồi tôi mới thắng một trận đấy!\nBé [BUF03] của tôi đỉnh cực kỳ luôn!\pCứ chờ đấy. Lần tới tôi sẽ đánh bại cậu\ncho xem! Thế nhé, bảo trọng nha!",
    "MC0035": r"Chào [BUF01][BUF05].\n[BUF02] đây.\pDạo này cậu thế nào rồi?\pTôi đang trên đà thăng hoa đây này.\nTôi vừa mới thắng một trận đấu giòn giã xong.\pLần tới khi chúng ta tái đấu,\nchắc chắn tôi sẽ không thua đâu!",
    "MC0036": r"[BUF01][BUF05] hả?\n[BUF02] đây.\p[BUF03] của tôi mạnh mẽ vô cùng!\nNó vừa mang lại cho tôi thêm một chiến thắng nữa đấy!\pTôi nóng lòng muốn tái đấu\nvới cậu quá rồi đây này.",
    "MC0037": r"Ồ, [BUF01][BUF05], cậu khỏe không?\nTôi là [BUF02] đây.\pMong là cậu vẫn bình an.\nTôi gọi để khoe là tôi vừa thắng trận xong đấy.\pBé [BUF03] của tôi đã chiến đấu đặc biệt kiên cường\nđể giành lấy chiến thắng này.\pHẹn gặp lại cậu nhé!",
    "MC0038": r"Ồ, [BUF01][BUF05], chào cậu nhé!\nTôi là [BUF02] đây!\pPokémon của cậu dạo này phong độ thế nào?\nPokémon của tôi vừa thắng một trận oanh liệt đấy!\pPhải nói là [BUF03] của tôi\nthi đấu xuất thần luôn!\pƯớc gì tôi có thể cho cậu tận mắt chứng kiến!\nHẹn gặp lại cậu nhé!",
    "MC0039": r"Ồ, [BUF01][BUF05], chào cậu…\nTôi là [BUF02] đây.\pCuộc sống dạo này của cậu thế nào rồi?\pPokémon của tôi dường như đang tràn trề\nsinh lực và nhiệt huyết.\pTôi vừa cùng các bé ấy giành chiến thắng trong một trận đấu.\nHẹn gặp lại sau nhé.",
    "MC0040": r"A, [BUF01][BUF05].\nTôi là [BUF02] đây.\pDạo này có tham gia trận đấu nào không?\nHôm nay tôi lại vừa thắng thêm một trận nữa rồi này!\pPhong độ ngút trời luôn! Ha ha ha ha!\nThôi, hẹn gặp lại nhé!",
    "MC0041": r"Chào [BUF01][BUF05].\nTôi là [BUF02] đây.\pCậu vẫn khỏe mạnh cả chứ?\nTôi thì lúc nào cũng dồi dào sinh lực!\pVừa nãy tôi lại thắng thêm một trận nữa rồi đấy.\nTôi chưa vội nhường bước cho lớp trẻ các cậu đâu nhé!",
    "MC0042": r"A, chào [BUF01][BUF05] nhé!\nTôi là [BUF02] đây!\pMong là cậu vẫn luôn khỏe mạnh.\nBước chân của tôi vẫn còn nhanh nhẹn lắm!\pVừa nãy tôi lại giành chiến thắng thêm lần nữa đấy.\nÔi, tôi chưa chịu thua đám người trẻ đâu nhé!\pHẹn gặp lại!",
    "MC0043": r"Ồ, chào [BUF01][BUF05].\nTôi là [BUF02] đây.\pGần đây tôi vừa thi đấu một trận, và [BUF03]\ncủa tôi đã thể hiện xuất sắc vô cùng!\pƯớc gì cậu có thể tận mắt chứng kiến,\n[BUF01][BUF05]. Bai bai nhé!",
    "MC0044": r"Chào [BUF01] nhé!\nTôi là [BUF02] đây.\pHửm? Khoan đã, cậu đang ở gần\n[BUF03] sao?\pÔi chà, thế thì phải làm một trận thôi!\nTôi sẽ đợi cậu nhé! Hẹn gặp lại!",
    "MC0045": r"Chào [BUF01] nhé!\nTôi là [BUF02] đây.\pỒ? Cậu tình cờ đang ở quanh khu vực\n[BUF03] ngay lúc này sao?\pCậu có muốn so tài một trận luôn không?\nTôi sẽ chờ cậu đấy! Hẹn gặp lại!",
    "MC0046": r"Chào [BUF01] nhé!\nTôi là [BUF02] đây nè.\pỒ này, có phải cậu đang ở gần\n[BUF03] lúc này không?\pCậu thấy thế nào nếu chúng ta đấu một trận\nngay bây giờ luôn?\pLần này tôi sẽ không thua nữa đâu!\nTôi đợi cậu đấy! Hẹn gặp lại sớm nhé!",
    "MC0047": r"Chào [BUF01][BUF05].\n[BUF02] đây.\pBây giờ cậu đang ở phương nào rồi?\nHả? [BUF03]?\pMuốn so tài ngay bây giờ không?\nTôi sẽ chờ cậu nhé. Hẹn gặp lại!",
    "MC0048": r"Chào [BUF01][BUF05] nha!\nTôi là [BUF02] đây.\lMọi chuyện của cậu thế nào rồi?\pGiờ cậu đang ở đâu cơ?\n[BUF03] ư?\pThế thì làm một trận tái đấu chớp nhoáng\nngay bây giờ luôn chứ nhỉ?\pTôi sẽ để mắt ngóng chờ cậu nhé.\nHẹn gặp lại sớm!",
    "MC0049": r"Chào [BUF01][BUF05].\n[BUF02] đây.\lPokémon của cậu dạo này khỏe chứ?\pỒ, thật thế sao? Cậu đang ở quanh\n[BUF03] à?\pThế thì chúng ta phải làm một trận tái đấu\nmới được rồi.\pTôi chờ được mà, chắc chắn rồi.\nHẹn gặp lại!",
    "MC0050": r"…Ừm, [BUF01][BUF05] phải không?\n[BUF02] đây nè…\pỒ, cậu tình cờ đang ở quanh khu vực\n[BUF03] sao?\pThế thì đấu một trận đi.\nÝ tôi là ngay bây giờ luôn ấy.\pTôi sẽ cho cậu xem các Pokémon của tôi.\nTôi sẽ đợi cậu nhé.",
    "MC0051": r"Ồ, [BUF01][BUF05], cậu khỏe không?\nTôi là [BUF02] đây.\pMong là cậu vẫn luôn khỏe mạnh.\nỒ, cậu đang ở gần [BUF03].\pVậy cậu có muốn so tài một trận\nvới tôi không?\pTôi sẽ đợi cậu nhé.\nHẹn gặp lại sớm!",
    "MC0052": r"Ồ, [BUF01][BUF05], chào cậu nhé!\nTôi là [BUF02] đây!\pCậu vẫn bắt nhịp tốt chứ?\nỦa, cậu đang ở gần [BUF03] hả?\pÔi chao, thế thì cậu không nghĩ là chúng ta\nnên làm một trận sao?\pĐừng bắt tôi phải đợi lâu đấy nhé!",
    "MC0053": r"Ồ, [BUF01][BUF05], chào cậu…\nTôi là [BUF02] đây.\pMọi việc của cậu thế nào rồi?\nỒ, cậu đang ở gần [BUF03].\pThế thì chúng ta nên thi đấu ngay bây giờ thôi.\pTôi đã sẵn sàng và đang chờ đây.\nNhanh lên đấy nhé!",
    "MC0054": r"A, [BUF01][BUF05].\nTôi là [BUF02] đây.\pA, hóa ra nơi cậu đang ở lúc này\nlà [BUF03] sao?\pChà chà, thế thì nhất định chúng ta phải so tài\nmột trận rồi, cậu thấy đúng không?\pTôi sẽ nán lại đây chờ cậu đấy!\nHẹn gặp lại thật sớm nhé!",
    "MC0055": r"Chào [BUF01][BUF05].\nTôi là [BUF02] đây.\lGiờ cậu đang ở nơi nào thế?\p[BUF03]?\nChỗ đó khá là gần đây đấy!\pCậu thấy sao nếu chúng ta thi đấu\nngay bây giờ?\pTôi có thể chờ được mà.\nHẹn gặp lại!",
    "MC0056": r"A, chào [BUF01][BUF05] nhé!\nTôi là [BUF02] đây!\pMong là cậu vẫn khỏe mạnh.\nỒ, cậu đang ở gần [BUF03]?\pVì chỗ đó chẳng xa xôi gì,\nmau đến gặp tôi để làm một trận đấu nhé.\pTôi sẽ chờ cậu.\nTạm biệt nhé.",
    "MC0057": r"Ôi, chào [BUF01][BUF05].\nTôi là [BUF02] đây.\pCậu đang ở đâu cơ? …[BUF03] á?\nGần xịt luôn đó.\pCậu có nghĩ là chúng ta nên làm\nmột trận so tài không?\pTôi sẽ ngóng tìm cậu đấy nhé!\nBai bai!",
    "MC0058": r"Chào [BUF01] nhé!\nTôi là [BUF02] đây.\pCậu có muốn so tài một trận với tôi không?\pTôi sẽ đợi cậu ở quanh khu vực\n[BUF03] nhé!",
    "MC0059": r"Chào [BUF01] nhé!\nTôi là [BUF02] đây.\pCậu có muốn tái đấu một trận\nvới tôi nữa không?\pCậu có thể tìm thấy tôi ở quanh khu vực\n[BUF03]. Tôi sẽ đợi đấy!",
    "MC0060": r"Chào [BUF01] nhé!\nTôi là [BUF02] đây.\pCác Pokémon của tôi đã mạnh hơn trước\nrất nhiều rồi đấy.\pTôi muốn thử xem chúng đã tiến bộ thế nào\nkhi đối đầu với Pokémon của cậu, [BUF01].\pThế nên, hãy làm một trận đấu nào!\pTôi sẽ đợi cậu ở quanh khu vực\n[BUF03] nhé.",
    "MC0061": r"Chào [BUF01][BUF05].\n[BUF02] đây.\lMọi chuyện của cậu thế nào rồi?\pDạo này các Pokémon của tôi đã trở nên\nkhá là mạnh mẽ rồi đấy.\pHey, cậu thấy thế nào nếu chúng ta so tài\nthêm một trận nữa?\pGặp nhau ở quanh khu vực\n[BUF03] nhé, được không?",
    "MC0062": r"Chào [BUF01][BUF05] nha!\nTôi là [BUF02] đây.\pCác Pokémon của tôi đang lớn lên\nvà phát triển rất tốt.\pTôi thực sự rất muốn so tài thêm\nmột trận nữa với cậu đấy.\pTôi sẽ ngóng chờ cậu ở quanh khu vực\n[BUF03]. Hẹn gặp lại sớm nhé!",
    "MC0063": r"Chào [BUF01][BUF05].\n[BUF02] đây.\lMong là mọi việc của cậu đều thuận buồm xuôi gió.\pTôi đang nghĩ là muốn tái đấu với cậu thêm một trận nữa. Cậu thấy sao?\pNếu có hứng so tài,\nhãy đến [BUF03] nhé.\pHẹn gặp lại!",
    "MC0064": r"…Ừm, [BUF01][BUF05] phải không?\n[BUF02] đây nè…\lThế nào rồi? Pokémon của cậu có tiến bộ không?\pCác bé của tôi chắc chắn đã mạnh hơn rồi.\nTôi muốn cho cậu thấy đấy.\pTôi sẽ ở quanh khu vực [BUF03].\nHãy đến tìm tôi để làm một trận đấu nhé.\pHẹn gặp lại sau.",
    "MC0065": r"Ồ, [BUF01][BUF05], cậu khỏe không?\nTôi là [BUF02] đây.\pMong là cậu vẫn dồi dào sức khỏe.\nCác Pokémon của tôi đang rất hăng hái.\pNếu có dịp ghé qua khu vực này,\nxin hãy cho tôi một cơ hội tái đấu nhé.\pTôi sẽ ở quanh [BUF03].\nTừ giờ đến lúc đó, tạm biệt nhé!",
    "MC0066": r"Ồ, [BUF01][BUF05], chào cậu nhé!\nTôi là [BUF02] đây!\lCác Pokémon của cậu thế nào rồi?\pPokémon của tôi ngày càng lợi hại hơn đấy.\nTôi muốn cho cậu thấy, [BUF01][BUF05].\pGiờ tôi đang ở quanh khu vực [BUF03],\nnên nếu tiện đường ở gần thì ghé đấu nhé.\pHi vọng sớm gặp lại cậu!",
    "MC0067": r"Ồ, [BUF01][BUF05], chào cậu…\nTôi là [BUF02] đây.\lThế nào rồi, mọi chuyện của cậu vẫn tốt chứ?\pPokémon của tôi đã mạnh hơn trước\nrất nhiều rồi đấy.\pTôi rất muốn so tài thêm trận nữa với cậu,\n[BUF01][BUF05].\pTôi sẽ ở quanh [BUF03].\nHãy ghé tìm tôi nếu cậu ở gần nhé.",
    "MC0068": r"A, [BUF01][BUF05].\nTôi là [BUF02] đây.\lGiờ cậu đang ở phương nào thế?\pPokémon của tôi đang tràn đầy sức sống.\nChúng dường như đang rất nóng lòng\nmuốn gặp lại Pokémon của cậu đấy, [BUF01][BUF05].\pHiện tại tôi đang ở quanh [BUF03].\nRất mong cậu sẽ đến tìm chúng tôi nhé.",
    "MC0069": r"Chào [BUF01][BUF05].\nTôi là [BUF02] đây.\pTôi muốn nói cho cậu hay, dạo này các Pokémon\ncủa tôi đã trở nên vô cùng cường tráng.\pTôi rất muốn nhìn thấy chúng so tài trong một trận đấu\nvới cậu đấy, [BUF01][BUF05].\pChúng tôi sẽ ở quanh khu vực [BUF03].\nHãy ghé thăm chúng tôi bất cứ lúc nào nhé!",
    "MC0070": r"A, chào [BUF01][BUF05] nhé!\nTôi là [BUF02] đây!\lCác Pokémon của cậu vẫn khỏe mạnh chứ?\pPokémon của tôi sung sức đến mức\ntrông chẳng có vẻ gì là sẽ thua trận cả!\pTôi chắc chắn rất muốn được đấu thêm\nmột trận nữa với cậu đấy.\pNếu cậu đang ở gần [BUF03],\nnhớ ghé qua tìm chúng tôi nhé.",
    "MC0071": r"Ồ, chào [BUF01][BUF05].\nTôi là [BUF02] đây.\lMong là cậu vẫn khỏe mạnh.\pỒ, phải rồi! Các Pokémon của tôi\nđã mạnh hơn trước rất nhiều đấy.\pCậu có nghĩ là chúng ta nên làm\nmột trận đấu không, [BUF01][BUF05]?\pChúng tôi sẽ đợi cậu ở quanh khu vực\n[BUF03].\pGhé qua gặp chúng tôi bất cứ lúc nào nhé, được chứ?",
    "MC0072": r"Tôi đây, người mê núi non\n[BUF02] đây nè!\pThế nào, từ lúc chúng ta gặp nhau, cậu đã\nbiết yêu vẻ đẹp của núi non nhiều hơn chưa?\pHiếm khi thấy cậu trên núi quá ta…\pLần tới, chúng ta sẽ gặp lại ở đâu đó\nquanh [BUF03] nhé.",
    "MC0073": r"Tôi là [BUF02] đây.\nXin chào cậu.\pTôi vừa mới kể về cậu cho một Huấn luyện viên\nmới vào nghề nghe đấy.\pTôi kể cho cô ấy về một Huấn luyện viên mạnh mẽ,\nngười luôn nuôi nấng Pokémon bằng tất cả tình yêu thương.\pTôi mong rằng cậu sẽ trở thành một Huấn luyện viên\nmà ai ai cũng phải kính phục.\pHi vọng chúng ta sẽ sớm gặp lại!",
    "MC0074": r"Xin chào! Tôi là [BUF02] đây.\pTôi thích mê nơi tôi đang đứng lúc này.\nKhông khí thật dễ chịu với những hương thơm ngọt ngào!\pTôi nghĩ có ai đó đã trồng Berry,\nvà hoa của chúng đang bung nở ngát hương.\pHẹn gặp lại cậu vào một dịp khác nhé!",
    "MC0075": r"Xin chào! Ba mươi năm kinh nghiệm thám hiểm,\n[BUF02] sẵn sàng phục vụ!\pCó vẻ như cậu đang hăng hái\ndu hành khắp đó đây nhỉ.\pCậu có phát hiện ra tàn tích cổ nào mới không?\nNếu có thì nhớ nói cho tôi biết với nhé!\pGiờ thì xin phép cậu,\ntôi phải tiếp tục khám phá các tàn tích đây.",
    "MC0076": r"Tôi là [BUF02] đây nè!\pCậu biết hôm nay tôi đang làm gì không?\nNgắm những con sóng vỗ từ bãi biển đấy!\pChao ôi… Những con sóng lấp lánh tuyệt đẹp.\nTừ góc này nhìn ra biển là đẹp nhất trần đời luôn.\lBụng tôi réo ầm ầm rồi, nên bai bai nhé!",
    "MC0077": r"Ngoàm ngoàm…\nỒ, chào cậu, tôi là [BUF02] đây nè.\lTôi thích nhất trần đời là được ăn trên bãi biển.\pTôi và các Pokémon của mình đều đang rất sung sức.\nNạp đầy năng lượng rồi nè!\lTôi đi bơi đây. Tạm biệt nhé!",
    "MC0078": r"Xin chào, [BUF02] đây…\pĐôi lúc tôi cảm thấy hơi mệt mỏi với danh xưng\nHuấn luyện viên Tinh anh này…\pAi ai cũng nghĩ tôi là một Huấn luyện viên\nhoàn hảo, và điều đó khiến tôi luôn phải gồng mình\nđể đáp ứng sự kỳ vọng ấy.\pNhưng tôi đoán đó là cái giá của việc trở thành\nmột Huấn luyện viên Tinh anh.\pTôi chỉ biết cắn răng cố gắng…\nvà mỉm cười gánh vác thôi.\pCậu là người duy nhất mà tôi có thể\ntrút bầu tâm sự như thế này đấy.\pNhưng lần tới khi gặp nhau,\ncậu đừng lo, tôi sẽ không than vãn nữa đâu!",
    "MC0079": r"Hú hồn, tôi là [BUF02] đây!\nCậu khỏe không nào?\pTôi đang huấn luyện Pokémon với mục tiêu\nlà đánh bại cậu đấy nhé.\pTôi không có ý định để thua thêm lần nữa\nkhi chúng ta tái đấu đâu.\pCó những người bạn Huấn luyện viên thật tuyệt phải không?\nNhất định gặp lại nhé!",
    "MC0080": r"[BUF02] đây…\nNgay lúc này, ở phía sau lưng cậu…\lChẳng phải có thứ gì đó… sao?\pSức mạnh của những linh hồn Pokémon\nđang yên nghỉ tại Mt. Pyre nơi đây…\pChúng đang thầm thì với tôi về cậu…\pCậu nên nhanh chân rảo bước rời đi\nvà đừng bao giờ quay đầu nhìn lại…\pHi hi hi…\nVĩnh biệt…",
    "MC0081": r"Tôi là [BUF02] đây.\nCậu khỏe không?\pCó thể trò chuyện từ khoảng cách xa như thế này\nthật là tiện lợi quá chừng phải không?\pTrước đây, mỗi khi muốn nói chuyện với ai,\ntôi toàn phải nhờ tài xế riêng của cha chở đi…\pTôi phải đi có việc rồi.\nRất vui vì đã được trò chuyện cùng cậu nhé.",
    "MC0082": r"Tôi là [BUF02] đây!\nCậu nghe chuyện này xem có tức không chứ?\pTôi thích Safari Zone lắm luôn á,\nnhưng hễ cứ bước vào đó là tôi bị lạc đường!\pBãi cỏ cao ngút ngàn khắp nơi!\nVà khuôn viên lại còn quá rộng mênh mông bát ngát!\pTrút bỏ được nỗi lòng thế này thấy nhẹ cả người!\pGiờ tôi lại xông vào Safari Zone tiếp đây!\nHẹn gặp lại sau nha!",
    "MC0083": r"Xin chào, [BUF02] đây.\nPhải, đúng thế, ta giàu nứt đố đổ vách, hiển nhiên rồi.\pTa phải nói cho cậu biết, khối tài sản của ta\nđã tăng thêm bội phần kể từ lần cuối ta gặp nhau.\pChưa hết đâu nhé, các Pokémon của ta\ncũng đã trở nên mạnh mẽ hơn nhiều.\pTa không khỏi cảm thấy dường như\ncả thế giới này sinh ra là vì ta vậy!\pỒ, không cần phải nói lời nào đâu!\nAi ai cũng đều hiểu rõ sự thật đó mà!\pÔi, thứ lỗi cho ta nhé, ta phải đi dự\nmột bữa tiệc tối trang trọng đây.",
    "MC0084": r"U fufufufu…\nTôi là [BUF02] đây nè…\pCậu đoán xem tôi đang chứng kiến cảnh gì nào?\nHai con [BUF03] đang quyết chiến với nhau đấy.\pCó lẽ tôi sẽ thử bắt lấy kẻ chiến thắng xem sao…\nU fufufufufu…\pTôi… giờ tôi bận chút việc rồi.\nTôi phải đi đây.",
    "MC0085": r"Ồ, [BUF02] đây nè!\pTôi vừa mới nghĩ là mình đã phát chán\ncon tàu Bị bỏ hoang Abandoned Ship này rồi.\pNhưng vì đã lỡ đến đây rồi,\nlại còn muốn đánh bại cậu một lần nữa,\nlnên tôi sẽ nán lại đây thêm một chút.\pNếu cậu có nhã hứng, sao không ghé qua\ntìm gặp tôi nhỉ?\pTôi nghĩ hôm nay sẽ là ngày mà tôi lấy hết can đảm\nthách đấu gã ở phòng bên cạnh một trận đấy.\pHẹn gặp lại cậu nhé!",
    "MC0086": r"Ta là [BUF02]!\nNgười đàn ông của biển cả!\pCậu biết ta nghĩ gì không?\pCác Huấn luyện viên ngoài biển khơi\nchính là những kẻ kiên cường nhất trong số những kẻ kiên cường!\pCậu nên học hỏi ta mà ra biển\nrèn luyện đi thôi…\pỐi chà, một ngọn sóng khổng lồ đang dâng lên kìa!\pCơ hội huấn luyện ngàn năm có một đây rồi!\nXin lỗi nhé, ta phải đi lướt sóng đây!",
    "MC0087": r"[BUF02] đây! Nghe này, tôi vừa dạy võ karate\ncho các Pokémon của mình đấy.\pThế nhưng giờ chúng nó còn giỏi hơn cả tôi rồi!\nTôi đánh tập với chúng toàn bị ăn đòn thua liểng xiểng!\pNhưng dẫu có thua Pokémon của mình,\ntôi tuyệt đối không chịu thua bất kỳ Huấn luyện viên nào khác đâu, chắc chắn đấy!\pChúng ta nhất định phải tái đấu trận nữa!\nÚi chà daaa!",
    "MC0088": r"Tôi đây, [BUF02] đây.\nChuyến hành trình của cậu diễn ra thế nào rồi?\p…Chà chà, thật thế sao?\nNghe đầy kịch tính và kích thích ghê!\pTôi nghĩ mình có thể sáng tác hẳn một ca khúc\nvề một trong những chuyến phiêu lưu của cậu đấy.\p…Ồ, cảm hứng dâng trào rồi đây này.\nNhững câu riff guitar đang réo rắt trong đầu tôi rồi.\pTôi phải mau chóng ghi lại giai điệu này cho tử tế mới được,\nnên tôi phải chuồn đây! Hẹn gặp lại sau nhé!",
    "MC0089": r"Tôi là [BUF02] đây…\nHãy lắng nghe bài hát mới của tôi nhé.\pLa la la, [BUF03], [BUF03]!\nTại sao em lại là [BUF03] ấy nhỉ?\lTại sao ta chẳng thể là em, [BUF03]?\lLa la, [BUF03] và [BUF02],\l[BUF02] cùng [BUF03]…\pĐiệp khúc lặp lại, âm thanh nhỏ dần…",
    "MC0090": r"Tôi là [BUF02] đây, cậu biết đấy,\nchuyên gia cắm trại cừ khôi!\pLúc chúng ta so tài, tôi đành chịu thua\ntrước thực lực của cậu.\pDẫu sao thì chuyên môn của tôi\nvẫn là cắm trại dã ngoại mà.\pNhưng dù thắng hay bại, tôi vẫn thích được so tài\nmỗi khi đi cắm trại.\pTái đấu với chúng tôi lần nữa nhé, được chứ?\nÀ, và cùng đi cắm trại nữa nha!",
    "MC0091": r"Tôi đây, chính là tôi, [BUF02] đây nè!\pThật lòng mà nói thì tôi cũng muốn leo\nnhững ngọn núi khác ngoài ngọn này nữa.\pNhưng mà tôi chẳng rõ liệu ở đó có nhiều\nquý cô xinh đẹp như ở Mt. Chimney không.\pNếu cậu biết ngọn núi nào khác mà có nhiều nàng xinh xắn,\nnhớ mách cho tôi biết với nhé!\pKhì khì khì, hẹn gặp lại sau nha!",
    "MC0092": r"… … … … … …\n… … … … … …\l[BUF02] đây…\p… … … … … …\n… … … … … …\lHôm nay chỉ có thế thôi…",
    "MC0093": r"Tôi là [BUF02] đây. Hôm nay, tôi cứ có\ncảm giác là sẽ được trò chuyện cùng cậu.\pKhao khát muốn đánh bại cậu trong tôi\ncứ ngày một lớn dần theo năm tháng.\pCậu cũng có một đối thủ truyền kiếp như thế đúng không?\nTôi ước gì người đó chính là mình…\pRất vui vì cậu đã lắng nghe tâm sự của tôi.\nHẹn gặp lại!",
    "MC0094": r"Tôi là [BUF02] đây.\pMỗi khi có một Huấn luyện viên cừ khôi ở gần,\nđôi lúc tôi có thể cảm nhận được điều đó bằng trực giác.\pCó phải cậu vừa đi ngang qua đây không, [BUF01][BUF05]?\nCó lẽ người đó chính là cậu đấy.\pTôi sẽ chờ đợi chuyến viếng thăm của cậu nhé.\nTạm biệt!",
    "MC0095": r"Xin chào, tôi là [BUF02] đây.\nGiọng cậu nghe rất khỏe khoắn, [BUF01][BUF05].\pTôi đã chu du khắp thế giới,\nnhưng phải công nhận rằng tôi có cảm tình đặc biệt\nvới vùng đất tuyệt đẹp này.\pTôi dự định sẽ lưu lại đây một thời gian.\nLiệu chúng ta có thể hội ngộ lần nữa chứ?\pTôi vẫn chưa hề quên những chiêu thức chói sáng\ncủa cậu đâu.\pRất mong có ngày được tái đấu.",
    "MC0096": r"Hức hức… Em là… [BUF02] đây…\n…Hu hu…\pHôm nay ở trên lớp em bị cô Roxanne mắng cho một trận te tua.\pNhưng em không hề ghét cô ấy chút nào đâu nhé.\pCô Roxanne chỉ ra cho em biết chính xác mình sai ở đâu để còn học hỏi mà.\pChắc chắn ngày mai em vẫn sẽ đi học\nở Trường đào tạo Huấn luyện viên!\pHẹn gặp lại sau nha!",
    "MC0097": r"Em là [BUF02] đây nè!\pHôm qua cô Roxanne đã cho phép em\nđược đấu một trận với cô ấy đấy.\pKết quả thế nào ư…\nThảm hại vô cùng, hỏi cũng thừa biết mà.\pNhưng em vẫn sướng rơn vì cô Roxanne\nđã đồng ý nhận lời thách đấu của em!\pCậu không tưởng tượng nổi là em ngưỡng mộ cô ấy\nnhiều đến mức nào đâu!\pEm sẽ thật sự tập trung học hành chăm chỉ!\nEm phải đi đây!",
    "MC0098": r"Chào cậu, mình là Anna đây! Hôm nay mình lại đi cùng cô em cộng sự Meg rồi nè.\pMình thật sự rất thích chăm sóc Meg và các Pokémon. Chúng đáng yêu lắm luôn!\pMình ước gì có thể chăm sóc chúng\nnhư thể anh chị em trong nhà vậy!\pỒ, chào Meg nha!\nEm đã mua bánh bao về chưa thế?\pHả? Đâu có, chị đâu có coi em\nnhư kẻ hầu người hạ đâu chứ!\pEm thua trận đấu mà, nên hình phạt là phải đi mua bánh mì thôi!\pChị đời nào coi em như người hầu chứ,\nMeg! Em là người đặc biệt với chị mà!\pGiờ mình phải đi rồi.\nĐến giờ ăn nhẹ rồi nè!",
    "MC0099": r"Tôi yêu Pokémon nhất trần đời!\nTôi là [BUF02] đến từ Câu lạc bộ Người hâm mộ đây!\pCậu nhất định phải nghe chuyện này mới được!\nBé Pokémon cưng xỉu của tôi…\pHí hí! Oa ha ha!\nTôi không thể tiết lộ thêm đâu! Bí mật đấy!\lĐáng yêu đến mức không bút nào tả xiết luôn!\pÔi, bé cưng [BUF03] của tôi đang nài nỉ xin một viên [S55][S56][S57][S58][S59] kìa!\pTrông cưng muốn xỉu luôn á!\pXin lỗi nhé, giờ tôi không buôn chuyện được rồi!\nLần tới cậu sẽ được nghe tiếp nhé!",
    "MC0100": r"Ô hô hô!\pTôi là [BUF02] đây! Tôi nóng lòng muốn kể cho cậu nghe về bé Pokémon cưng của tôi quá rồi!\pXin cậu đấy, cậu nhất định phải lắng nghe chuyện này.\nChuyện là về bé cưng [BUF03] của tôi đấy.\pMỗi khi có ai đó bế bé lên,\nbé liền nhảy tót ngay vào vòng tay của tôi!\pÔi… Ôi chao… Có điều gì trên đời này\ncòn hạnh phúc hơn thế nữa không chứ?\pÔi, cảm giác lâng lâng như trên thiên đường vậy!\pTôi rất vui vì có thể sẻ chia một phần niềm hạnh phúc này cùng với cậu.\pThôi, tôi phải đi đây.\nTạm biệt nhé!",
    "MC0101": r"Ta là… [BUF02].\nNgười đời thường gọi ta là một Bậc thầy.\pNhưng có một điều mà ta luôn thấu suốt.\nBằng chính sức mình, ta không thể nào trở thành một Bậc thầy được.\pChỉ khi có sự kề vai sát cánh của Pokémon,\nmột Huấn luyện viên mới có thể vươn tới cảnh giới Bậc thầy.\pHừm! Ta tin rằng mình vừa nói ra một điều gì đó vô cùng uyên thâm và sâu sắc đấy!\pChúc cậu luôn giữ vững tinh thần phấn chấn!",
    "MC0102": r"Bà là [BUF02] đây.\nRất vui được trò chuyện cùng cháu nhé!\pNgâm mình trong bồn suối nước nóng này khiến bà thấy khoan khoái và tràn đầy sức sống hẳn ra.\pKể từ ngày gặp cháu, bà đã thi đấu với nhiều Huấn luyện viên trẻ, nhưng cháu vẫn là người xuất sắc nhất trong số họ.\pBà mường tượng khi về già cháu chắc chắn sẽ trở thành một Bậc thầy cho mà xem! Ô hô hô hô…",
    "MC0103": r"Da-hú! [BUF02] đây nè!\nCó chuyện gì thế?\pCó thể là do tôi tưởng tượng thôi, nhưng mỗi khi thắng trận, chiếc quần đùi của tôi có vẻ như mặc sướng hơn hẳn ấy. Về mặt chất liệu ấy mà.\pÝ tôi là sao á?\nHơi khó giải thích một chút, nhưng mà…\lNói sao cho đúng đây ta…\lQuần của tôi mặc thấy mượt mà như lụa vậy đó!\pVà lúc tôi so tài với cậu, [BUF01][BUF05],\nchiếc quần của tôi cảm giác cứ nhờn nhợt và thô ráp làm sao ấy.\p… … … … … …\nCậu không thực sự tin vào điều đó đấy chứ?\lHì hì hì, thế thôi nhé! Tạm biệt nha!",
    "MC0104": r"A-hôi!\n[BUF02] đây nè!\pNhư mọi khi, tôi vẫn đang miệt mài câu cá đầy say mê!\pLiệu còn nơi nào khác ngoài biển cả và sông ngòi mà tôi có thể buông cần được không nhỉ?\pTrong lòng tôi luôn có một thôi thúc mãnh liệt muốn được câu cá ở bất cứ nơi đâu!\pÔi trời đất ơi, tức thật đấy!\nDây câu của tôi bị rối tung lên rồi!\pTôi phải đi gỡ đây!\nNhớ tìm giúp tôi vài điểm câu cá mới nhé!",
    "MC0105": r"Chào đằng ấy! Tôi là [BUF02] đây.\nCậu vẫn cứ sống thong thả tự tại chứ?\pCậu biết không, từ thuở ấu thơ,\ntính tôi lúc nào cũng điềm tĩnh, an nhiên vậy đó.\pTôi chưa bao giờ là người chịu được căng thẳng hay thích vội vã hấp tấp cả.\pThế mà ai mà ngờ được chứ,\ngiờ tôi lại trở thành một Vận động viên ba môn phối hợp đấy.\pCuộc đời đưa đẩy ta đi đâu chẳng ai lường trước được, nếu cậu hiểu ý tôi.\pHiện giờ cậu là một Huấn luyện viên, nhưng tương lai có ra sao thì ai biết được, nhỉ?\pThử tưởng tượng bản thân trở thành một người thầy giáo, hay một người nghệ sĩ xem. Ngầu phết đấy chứ?\pNhưng mà này, cứ thư thả thôi. Sống thật thoải mái nhé.\nHẹn gặp lại sau nha.",
    "MC0106": r"[BUF02] đây nè!\nTôi đang đạp xe vi vu đây.\pTôi yêu thích bơi lội và chạy bộ,\nnhưng đạp xe mới chính là tình yêu đầu đời của tôi!\pCảm giác toàn thân như được hòa làm một với những làn gió vậy.\pNó làm tôi phấn chấn tột độ cứ như thể mình đang bay lượn trên không trung!\pĐược rồi! Hôm nay, tôi sẽ thiết lập một kỷ lục mới trên Con đường Đạp xe!\pCậu cũng nên thử sức thách đấu xem sao nhé!\nHẹn gặp lại!",
    "MC0107": r"Hế lô, [BUF02] đây nè! Tôi đang ở ngay\ngiữa chặng đua ba môn phối hợp đây!\pNhưng này, tôi lúc nào cũng có thời gian\nđể buôn dưa lê tán gẫu hết á!\pLuyện tập cùng Pokémon mang lại cảm giác\ntuyệt đỉnh vô cùng!\pChẳng cần mở miệng thốt một lời, chúng tôi vẫn thấu hiểu và đồng điệu như chung một nhịp tim.\pThật là truyền cảm hứng biết bao!\pHộc… Vừa chạy vừa buôn chuyện…\nTôi đang kiệt cả sức rồi…\lHộc… Phải…đi…đây…",
    "MC0108": r"Chào cậu, [BUF02] đây.\nNếu cậu muốn nâng cao sức bền,\lrèn luyện trên độ cao lớn chính là chân ái đấy!\pHãy thử chạy bộ trên đỉnh núi xem sao.\nĐảm bảo cậu sẽ thở không ra hơi chỉ trong chớp mắt!\pTôi cũng đang bị thiếu oxy trầm trọng rồi đây này!\nHẹn gặp lại nhé!",
    "MC0109": r"Ồ, [BUF02] đây, xin chào cậu.\pTôi bơi lội ròng rã suốt mà dường như\nvẫn chưa tài nào tới được Ever Grande City.\pCó khi nào tôi đang bơi vòng tròn quanh một chỗ không nhỉ.\pKhông, không, làm sao mà có chuyện đó được chứ.\nOa ha ha ha.\lBảo trọng nhé!",
    "MC0110": r"Chào cậu, [BUF02] đây…\nỐi chao!\pTõm!\pỦm-ủm-ủm-ủm…\pBõm!\pPhì-phì! Phì-phì!\pHây! Xin lỗi cậu về vụ đó nhé!\nTôi vừa mới thoa một ít dầu chống nắng lên người.\pThế là chiếc Pokénav trơn tuột khỏi tay tôi\nrơi tõm ngay xuống nước!\pNhưng mà chao ôi, Pokénav của tập đoàn Devon chế tạo bền thật đấy. Bị ngâm nước thế mà vẫn sống nhăn!\pDù sao thì tôi cũng đang bận tắm nắng rồi,\nnên để dịp khác chúng ta lại trò chuyện nhé.",
    "MC0111": r"Xin chào, [BUF02] đây nè.\pTrong ba môn thi đấu phối hợp,\ntôi thích môn bơi lội nhất trần đời.\pNhưng nếu tôi cứ ngâm mình dưới biển quá lâu,\nliệu da dẻ tôi có bị nhăn nheo như quả mận khô không nhỉ?\pOoh, ba môn phối hợp đúng là một bài kiểm tra thể lực đầy khắc nghiệt đối với sức chịu đựng của con người! Tạm biệt nha!",
    "MC0112": r"Chào [BUF01][BUF05].\n[BUF02] đây.\pPokémon của cậu dạo này thế nào rồi?\pCác Pokémon Rồng của tôi dường như đang ở\nphong độ đỉnh cao nhất. Tạm biệt nhé.",
    "MC0113": r"[BUF02] đây.\p[BUF03] của tôi đã trở nên mạnh mẽ hơn\nrất nhiều so với lần trước rồi đấy.\pTôi sẽ không để thua cậu thêm lần nào nữa đâu.\nCứ chờ đấy tới lần sau nhé!\pHẹn gặp lại sau!",
    "MC0114": r"Là [BUF02] đây.\pTa vẫn đang tiếp tục khổ luyện\nthuật ẩn thân của nhẫn giả.\pNhưng ta đã thành công quá mức rồi.\nChẳng có một ai có thể tìm thấy ta cả.\lSự thành công này chỉ mang lại cho ta nỗi cô đơn…\pNhư làn khói hư ảo, ta biến mất đây!\nVĩnh biệt!",
    "MC0115": r"Tôi là [BUF02] đây.\nTôi vẫn miệt mài luyện tập kể từ khi chúng ta gặp nhau.\pBé [BUF03] của tôi đang trở nên\nkhá là dũng mãnh rồi đấy.\pĐúng như tôi nghĩ, tập luyện trên bãi biển mang lại hiệu quả rất tuyệt. Tạm biệt nhé!",
    "MC0116": r"Cậu khỏe không?\nTôi là [BUF02] đây nè.\pTôi tự hỏi không biết bao giờ đám tro núi lửa đáng ghét này mới chịu ngừng rơi đây?\pNếu tro phủ quá dày, nó sẽ che mất\nhoa văn xinh xắn trên chiếc dù che nắng của tôi mất…\pHứa là chúng mình sẽ gặp lại nhau nhé!",
    "MC0117": r"Chào cậu, [BUF02] đây.\pCậu có biết rằng thả nổi trên biển dễ hơn\nnhiều so với trong hồ bơi không?\pChỉ cần nằm yên bất động, cơ thể cậu\nsẽ tự động nổi bồng bềnh trên mặt nước thôi.\pNhưng mà nếu cậu thả nổi quá lâu,\nhãy cẩn thận kẻo bị sóng cuốn trôi\nđi quá xa bờ đấy nhé.\p…Khoan đã, rốt cuộc mình đang ở đâu thế này?\nTôi phải bơi về thôi!",
    "MC0118": r"Ồ, [BUF01][BUF05], xin chào nhé!\nTôi là [BUF02] đây.\lHiện giờ tôi đang ở tít trên núi cao.\pThế nhưng mặt đất ở đây gồ ghề quá xá.\nTôi không tài nào dựng lều ở đây được…\pÔi, tôi vừa nảy ra một sáng kiến tuyệt hảo!\pCó lẽ tôi có thể nhờ các Pokémon của mình\ndậm phẳng lì nền đất ở chỗ này!\pTôi sẽ đi thử ngay đây!\nBai bai nhé!",
    "MC0119": r"Ôi, chào chào cậu, em là [BUF02] đây nè!\pEm đang cùng nuôi dưỡng Pokémon với Liv đấy!\nTụi em đang cố gắng hết sức mình luôn!\pNếu tụi em cố gắng chăm chỉ hơn nữa, liệu tụi em có thể trở thành số một được không ta? Bai bai nha!",
    "MC0120": r"[BUF02] đây!\pTôi là một Thủy thủ, thế nhưng lúc này\ntôi lại chẳng hề ở trên một con tàu nào cả.\pĐiều đó khiến tôi cứ thắc mắc mãi--một Thủy thủ trên cạn thì nên được gọi là gì nhỉ?\pĐó là điều mà tôi cứ trăn trở mãi\ntrong lúc đăm chiêu nhìn ra những ngọn sóng xa xăm.\pĐược rồi, hẹn lần tới nhé!",
    "MC0121": r"Tôi là [BUF02] đây.\nSao rồi? Cậu đã thu phục thêm được bé Pokémon nào chưa?\pNếu cậu bắt được một bé Pokémon mới,\nnhớ phải đến khoe với tôi đấy nhé.\pTôi sẽ không vòi vĩnh xin cậu đâu, thật lòng đấy.\nTôi sẽ đợi nhé. Hẹn gặp lại.",
    "MC0122": r"Tôi là [BUF02] đây.\pCậu có đang nuôi dưỡng các Pokémon của mình\ntheo phương pháp tối ưu nhất không đấy?\pKhông khí ở nơi tôi đang đứng trong lành tuyệt đối.\nĐây quả thực là môi trường hoàn hảo\nđể chăm sóc và huấn luyện Pokémon.\pNếu cậu muốn tập trung phát triển Pokémon,\ncậu nên ghé qua khu vực [BUF03] xem sao nhé. Bảo trọng nha.",
    "MC0123": r"Xin chào, tôi là [BUF02] đây.\pTôi vừa thưởng cho bé [BUF03] của mình một viên [S55][S56][S57][S58][S59].\nBé ấy có vẻ thích thú và hào hứng lắm.\pXem ra các Pokémon cũng có những sở thích và khẩu vị riêng đối với từng loại [S55][S56][S57][S58][S59]S.\pTôi thấy điều đó thật sự rất thú vị.\nCậu hãy nhớ giữ gìn sức khỏe nhé.",
    "MC0124": r"[BUF02] đây.\pNếu biết hòa hợp và đồng lòng cùng Pokémon,\ncon người hoàn toàn có thể sinh tồn thoải mái giữa thiên nhiên hoang dã.\pMọi người ai cũng nên thấu hiểu điều đó và gắn kết với Pokémon nhiều hơn nữa.\pĐó sẽ là một thế giới lý tưởng.\nTôi thực sự luôn tin là như vậy.\pTôi thấy cậu đang đi rất đúng hướng đấy!\nHẹn gặp lại sau nhé!",
    "MC0125": r"Chào cậu, [BUF02] đây! Cậu biết rồi đấy,\nHuấn luyện viên lúc nào cũng chuẩn bị sẵn sàng mọi thứ!\p[BUF01][BUF05], cậu đã mang đủ vật phẩm cần thiết chưa?\nCác Pokémon của cậu có đang ở trạng thái sung sức nhất không?\pLuôn duy trì mọi thứ quanh mình trong tình trạng hoàn hảo nhất chính là bí quyết để duy trì chuyến hành trình dài lâu đấy.\pTôi phải đi kiểm tra lại đồ đạc của mình đây!\nLuôn luôn cảnh giác nhé!",
    "MC0126": r"[BUF02] đây nè!\nChính là [BUF02] đây nè!\p[BUF03] là một tuyến đường vô cùng tấp nập,\nnên ngày nào tôi cũng được đủ loại Huấn luyện viên đến thách đấu.\pHôm nay, tôi đã thắng tận năm trận và chỉ để thua có ba trận thôi đấy nhé!\pCòn cậu hôm nay thế nào rồi?\nLần tới gặp nhau nhớ kể cho tôi nghe với nhé, được không?",
    "MC0127": r"Tôi đây, [BUF02] đây.\pTôi rất được mọi người chú ý vì sở hữu vô số Pokémon Hệ Bọ, đúng không nào?\pThế là hôm nay tôi bèn mang cả bầy bọ cưng yêu thích nhất đến trường học.\pAi ngờ bạn gái mà tôi thích lại òa lên khóc nức nở!\nCậu cứ việc cười đi nếu cậu muốn.\pTôi nhất định phải tìm cách chỉ cho bạn ấy thấy Pokémon Hệ Bọ cuốn hút và quyến rũ đến nhường nào mới được.\pSụt sịt…\nHẹn gặp lại nha!",
    "MC0128": r"Hộc! Hộc! Hộc! Hộc!\pChào nhé! [BUF02] đây nè! Hộc! Hộc!\pVừa cố buôn chuyện…\nlại vừa leo núi…\lQuả là bài tập nặng nhọc dã man… Hộc! Hộc!\pHự! Ái chà…\nĐoạn này dốc đứng hơn rồi…\lChúng ta sẽ… nói chuyện sau nhé…\lHộc! Hộc! Hộc!",
    "MC0129": r"Ồ, chào cậu!\pTôi vẫn đang cùng nàng Kira đi săn tìm kho báu đây!\pCó khi ở chốn này chẳng có kho báu nào hết đâu…\pNhưng điều quan trọng nhất đối với tôi\nlà được kề vai sát cánh tìm kiếm cùng với Kira.\pÔi, này, Kira em yêu ơi!\nS-sao em lại giận dỗi thế kia?\pAnh đâu có lơ là em đâu mà, em yêu!\nEm là duy nhất và mãi mãi của anh mà!\p…[BUF01], tôi phải cúp máy đây, tạm biệt nhé!",
    "MC0130": r"[BUF02] đây nè!\pTôi lại vừa ghé Nhà thi đấu Dewford Gym\nđể rèn luyện thêm đấy.\pAnh Brawly, Thủ lĩnh Nhà thi đấu, dường như\ngiờ đây đã mạnh mẽ và cứng cỏi hơn trước nhiều rồi.\pNghe đâu là nhờ được tôi luyện\ngiữa những con sóng dữ dội…\pNhưng mà anh ấy vẫn phong độ và ngầu lòi như mọi khi.\nCác quý cô mê anh ấy như điếu đổ luôn á!\lThật lòng mà nói điều đó làm tôi ghen tị muốn chết.\pTôi tự hỏi… Liệu Bruno, bạn thân của anh ấy, có cùng một kiểu như Brawly không nhỉ?\pCậu biết đấy, kiểu người lúc nào cũng đẫm mồ hôi hay bốc mùi phong trần, rồi hay thích gọi người khác là “ngọn sóng lớn” này nọ ấy.\pNhưng mà này, cái thói ghen tị này trông chẳng đẹp đẽ chút nào nhỉ?\pCoi như chúng ta chưa từng có cuộc trò chuyện này nhé, thấy sao? Tạm biệt nha!",
    "MC0131": r"Thật là một niềm vinh hạnh khi được trò chuyện\nvới một Huấn luyện viên trẻ tuổi tài ba như cháu.\pTa tin rằng dẫu ở bất kỳ độ tuổi nào,\ncháu vẫn sẽ luôn tìm thấy niềm vui bên các Pokémon.\pChẳng phải sẽ thật tuyệt vời nếu cháu có được\nmột mối gắn kết tri kỷ như vợ chồng ta sao?\pDĩ nhiên rồi, [BUF01][BUF05], ngay lúc này cháu đã nhận được\nsự tin tưởng và bầu bạn chân thành từ các Pokémon của mình rồi.\pCháu đã hội tụ đủ phẩm chất cho những mối quan hệ\nbền chặt và dài lâu từ bây giờ rồi đấy!\pHa ha ha!\nĐừng bao giờ nản lòng thoái chí nhé!",
    "MC0132": r"Chào cậu, em là [BUF02] đây nè!\nTụi em vừa mới thắng một trận đấu xong đấy!\pTụi em chẳng mấy khi thắng đâu, nhưng đối thủ lại là một anh Chàng bơi lội đẹp trai siêu cấp ngầu lòi.\pThế là bà chị gái của em tức điên cả người!\pBả muốn giả vờ yếu đuối để ghi điểm tạo ấn tượng cơ!\pBả lúc nào cũng mắng té tát vào mặt em bất kể thắng hay bại!\p[BUF01][BUF05], lần tới gặp bà ấy cậu nhớ nói giúp em vài câu nhé?\pThế nhé, hẹn gặp lại nha!",
    "MC0133": r"Tôi là [BUF02] đây, đúng vậy.\nHôm qua tôi vừa ra khơi ngoài biển cả.\pTôi đã rất hy vọng sẽ tìm được một tàn tích mới\nđể thỏa sức khám phá.\pThế nhưng chẳng hiểu sao các đợt thủy triều\nlại cuốn tôi trôi dạt về đúng điểm xuất phát ban đầu.\pTôi chiến đấu vẫn còn yếu ớt lắm…\nCứ tự nhiên cười nhạo tôi nếu cậu muốn…\lNhưng tôi tuyệt đối sẽ không bỏ cuộc đâu.\pRồi sẽ có một ngày tôi tự tay khai phá\nđược một tàn tích mới cho mà xem!\pĐó là tất cả những gì tôi muốn bày tỏ!\nTạm biệt cậu nhé!",
    "MC0134": r"A-hôi xin chào!\nTôi đây, [BUF02] đây nè!\lHiện giờ tôi đang lênh đênh ngoài Route 108 đây!\lNói cách khác, chính là nơi tôi vẫn cắm chốt từ trước đến giờ!\pHôm nay, có một cô nàng Bơi lội xinh đẹp tuyệt trần\nvừa bơi lướt qua chỗ tôi đấy!\pThế là tôi bèn hét lớn một tiếng làm cô ấy giật thót mình!\pVà cô ấy đã tặng cho tôi một ánh nhìn hình viên đạn cháy mắt luôn!\pBản tin từ Route 108 đến đây là hết!\nĐược phát thanh trực tiếp bởi phóng viên [BUF02]!",
    "MC0135": r"[BUF02] đây nè!\pTôi đang hơi bận một chút, nhưng tôi nghĩ\nmình nên cho cậu hay rằng hôm nay tôi lại vừa đánh bại\nđược thêm năm Huấn luyện viên nữa rồi đấy.\pNếu cứ duy trì được phong độ và đà tiến này, rất có thể\ntôi sẽ đánh bại cậu trong lần so tài tới cho xem.\pTôi nghĩ hai chúng ta sẽ là những đối thủ xứng tầm đấy.\nTạm biệt cậu nhé!",
    "MC0136": r"Chào cậu! [BUF02] đây nè.\nTôi vừa nghe ngóng được tin sốt dẻo rồi nhé!\pNghe đồn cậu đã thể hiện xuất sắc phi thường\ntại [BUF03] đấy.\pThật là đỉnh chóp, [BUF04] trận thắng liên tiếp cơ đấy?\nHẹn gặp lại nhé!",
    "MC0137": r"Chào cậu, [BUF02] đây nè!\nTôi vừa nghe ngóng được tin về cậu đấy!\pNgười ta bảo cậu đã thắng một mạch [BUF04] trận liên tiếp\ntại [BUF03].\pĐặc biệt và xuất sắc quá đi thôi! Tôi cũng phải cố gắng rèn luyện hơn nữa mới được! Hẹn gặp lại nhé!",
    "MC0138": r"Chào [BUF01] nhé!\nTôi là [BUF02] đây nè.\pTôi nghe nói cậu đã làm mưa làm gió\ntại [BUF03] đấy!\pMột chuỗi thắng khủng khiếp lên tới [BUF04] trận…\nĐúng là một kỷ lục phi thường phải không nào?\pTôi cũng phải chấn chỉnh lại phong độ mới được!\nHẹn gặp lại cậu sớm nhé!",
    "MC0139": r"Chào [BUF01][BUF05].\n[BUF02] đây. Có chuyện gì thế?\pĐang có tin đồn lan truyền rằng\ncậu vừa lập chuỗi [BUF04] trận thắng liên tiếp\ntại [BUF03] đấy.\pTôi cũng phải nỗ lực bứt phá hơn nữa mới được.\nHẹn gặp lại!",
    "MC0140": r"Chào [BUF01][BUF05] nha!\nTôi là [BUF02] đây.\pCậu vừa ghé qua [BUF03]\nvà thắng liền một mạch [BUF04] trận sao?\lQuả là một kỳ tích đáng nể đấy chứ!\pTôi phải huấn luyện thêm cho các Pokémon của mình thôi.\nHẹn sớm gặp lại nhé!",
    "MC0141": r"Chào [BUF01][BUF05].\n[BUF02] đây. Cậu vẫn khỏe chứ?\pNhân tiện, tôi nghe nói cậu vừa lập nên kỳ tích\n[BUF04] trận toàn thắng liên tiếp tại [BUF03] đấy.\pĐiều đó truyền cảm hứng cho tôi tập trung\nhuấn luyện đội hình của mình hơn nữa.",
    "MC0142": r"…Ừm, [BUF01][BUF05] phải không?\n[BUF02] đây nè…\pÀ ừ, lúc nãy cậu vừa ở bên\n[BUF03] có đúng không?\pVà cậu đã toàn thắng liên tiếp [BUF04] trận đấu liền.\pÔi, một con Pokémon quý hiếm vừa lướt qua kìa!\nTôi phải đuổi theo đây!",
    "MC0143": r"Ồ, [BUF01][BUF05], cậu khỏe không?\nTôi là [BUF02] đây.\lMong là cậu vẫn dồi dào sức khỏe.\pÀ mà chắc chắn là vậy rồi. Tôi vừa nghe tin\ncậu đã thắng liên tiếp [BUF04] trận đấu tại [BUF03] đấy.\pThật sự vô cùng ấn tượng!\nChúc cậu sẽ luôn giữ vững phong độ thành công nhé.",
    "MC0144": r"Ồ, [BUF01][BUF05], chào cậu nhé!\nTôi là [BUF02] đây!\pTôi nghe tin rồi nhé! Chuỗi [BUF04] trận toàn thắng của cậu tại [BUF03] ấy!\pNgầu đét luôn á!\nTôi cũng phải nỗ lực hơn nữa mới được!",
    "MC0145": r"Ồ, [BUF01][BUF05], chào cậu…\nTôi là [BUF02] đây.\pCậu vừa thắng liên tiếp [BUF04] trận đấu tại [BUF03] sao?\pĐó quả thực là một thành tựu đáng nể.\nTôi cần phải chăm chỉ nỗ lực hơn nữa.",
    "MC0146": r"A, [BUF01][BUF05].\nTôi là [BUF02] đây.\pTôi nghe phong phanh cậu đang là nỗi khiếp sợ\ntại [BUF03] đấy à?\pCậu đã thắng cái gì mà tận [BUF04] trận liên tiếp cơ đấy?\pCậu cừ thật đấy, quả là cao thủ.\nKhông biết tôi có thể thắng được bao nhiêu trận đây nhỉ?",
    "MC0147": r"Chào [BUF01][BUF05].\nTôi là [BUF02] đây.\lCậu vẫn khỏe mạnh chứ?\pCó người vừa truyền tai nhau tin tức về cậu đấy.\nRằng cậu đã thắng liên tiếp [BUF04] trận đấu\ntại một nơi có tên là [BUF03] sao?\pĐúng là một giai thoại đáng kinh ngạc.\nHẹn gặp lại!",
    "MC0148": r"A, chào [BUF01][BUF05] nhé!\nTôi là [BUF02] đây!\lMong là cậu vẫn dồi dào sức khỏe.\pNgười ta đồn rằng cậu vừa thắng liên tiếp [BUF04] trận\ntại [BUF03] đấy.\pTôi thật sự khâm phục nguồn năng lượng dồi dào của cậu!\nTạm biệt nhé.",
    "MC0149": r"Ôi, chào [BUF01][BUF05].\nTôi là [BUF02] đây.\pTôi vừa nghe chuyện về cậu đấy!\nChẳng phải cậu vừa thắng liên tiếp tận [BUF04] trận\ntại [BUF03] sao?\pCậu đúng là nguồn cảm hứng lớn lao!\nBai bai nhé!",
    "MC0150": r"Chào cậu! [BUF02] đây nè.\nTôi vừa nghe ngóng được tin tức rồi nhé!\pNghe đồn cậu đã thể hiện xuất sắc phi thường\ntại [BUF03] đấy.\pThật là đáng kinh ngạc--[BUF04] trận toàn thắng liên tiếp cơ đấy?\nHẹn gặp lại nhé!",
    "MC0151": r"Chào cậu, [BUF02] đây nè!\nTôi vừa nghe mọi người bàn tán về cậu đấy!\pNgười ta bảo cậu đã thắng liền một mạch [BUF04] trận\ntại [BUF03].\pXuất sắc và đặc biệt quá đi thôi! Tôi cũng phải cố gắng nhiều hơn nữa mới được! Hẹn gặp lại nhé!",
    "MC0152": r"Chào [BUF01] nhé!\nTôi là [BUF02] đây nè.\pTôi nghe nói cậu đã càn quét khắp nơi\ntại [BUF03] đấy!\pMột chuỗi thắng hiển hách lên tới [BUF04] trận…\nĐúng là một kỷ lục phi thường phải không nào?\pTôi cũng phải chấn chỉnh lại tinh thần mới được!\nHẹn gặp lại cậu sớm nhé!",
    "MC0153": r"Chào [BUF01][BUF05].\n[BUF02] đây. Dạo này thế nào rồi?\pĐang có tin đồn râm ran khắp chốn rằng\ncậu vừa lập nên chuỗi [BUF04] trận toàn thắng liên tiếp\ntại [BUF03] đấy.\pTôi cũng phải tăng tốc bứt phá hơn nữa mới được.\nHẹn gặp lại!",
    "MC0154": r"Chào [BUF01][BUF05] nha!\nTôi là [BUF02] đây.\pCậu vừa ghé qua [BUF03]\nvà thắng liền một mạch [BUF04] trận sao?\lKỳ tích đáng nể quá chừng luôn đấy!\pCòn tôi ư? Tôi thấy mình cũng đang tiến bộ dần đều rồi.\nHẹn sớm gặp lại nhé!",
    "MC0155": r"Chào [BUF01][BUF05].\n[BUF02] đây. Cậu khỏe chứ?\pNhân tiện, tôi nghe nói cậu vừa hoàn thành kỳ tích\n[BUF04] trận thắng liên tiếp tại [BUF03] đấy.\pBản thân tôi cũng phải nỗ lực cố gắng hơn nữa thôi!\nHẹn sớm gặp lại nhé!",
    "MC0156": r"…Ừm, [BUF01][BUF05] phải không?\n[BUF02] đây nè…\pÀ ừ, lúc nãy cậu vừa ở bên\n[BUF03] có đúng không?\pVà cậu đã thắng liền một mạch [BUF04] trận đấu.\pÔi, một con Pokémon hiếm vừa chạy qua kìa!\nTôi phải đuổi theo đây!",
    "MC0157": r"Ồ, [BUF01][BUF05], cậu khỏe không?\nTôi là [BUF02] đây.\lMong là cậu vẫn dồi dào sức khỏe.\pÀ mà chắc chắn là vậy rồi. Tôi vừa nghe tin\ncậu đã thắng liên tiếp [BUF04] trận đấu tại [BUF03] đấy.\pThật sự vô cùng ấn tượng!\nTôi cũng phải lo rèn luyện thêm cho các Pokémon của mình thôi!",
    "MC0158": r"Ồ, [BUF01][BUF05], chào cậu nhé!\nTôi là [BUF02] đây!\pTôi nghe tin rồi nhé! Chuỗi [BUF04] trận toàn thắng của cậu tại [BUF03] ấy!\pNgầu đét luôn á!\nTôi cũng phải nỗ lực hơn nữa mới được!",
    "MC0159": r"Ồ, [BUF01][BUF05], chào cậu…\nTôi là [BUF02] đây.\pCậu đã toàn thắng liên tiếp [BUF04] trận tại [BUF03] sao?\pĐó quả là một thành tựu xuất sắc.\nTôi cần phải nỗ lực chăm chỉ hơn nữa.",
    "MC0160": r"A, [BUF01][BUF05].\nTôi là [BUF02] đây.\pTôi nghe người ta kháo nhau cậu đang là nỗi khiếp sợ\ntại [BUF03] đấy à?\pCậu đã thắng cái gì mà tận [BUF04] trận liên tiếp cơ đấy?\pCậu cừ thật đấy, quả là cao thủ.\nKhông biết tôi có thể thắng được bao nhiêu trận đây nhỉ?",
    "MC0161": r"Chào [BUF01][BUF05].\nTôi là [BUF02] đây.\lCậu vẫn khỏe mạnh chứ?\pCó người vừa truyền tin tức về cậu cho tôi đấy.\nRằng cậu đã thắng liền một mạch [BUF04] trận\ntại một địa danh có tên là [BUF03] sao?\pĐúng là một giai thoại đáng kinh ngạc.\nHẹn gặp lại!",
    "MC0162": r"A, chào [BUF01][BUF05] nhé!\nTôi là [BUF02] đây!\lMong là cậu vẫn luôn khỏe mạnh.\pNgười ta kể rằng cậu vừa thắng liên tiếp [BUF04] trận\ntại [BUF03] đấy.\pTôi thật sự kính nể nguồn sinh lực dồi dào của cậu!\nTạm biệt nhé.",
    "MC0163": r"Ồ, chào [BUF01][BUF05].\nTôi là [BUF02] đây.\lTôi vừa nghe ngóng được chuyện về cậu đấy!\pChẳng phải cậu vừa thắng liên tiếp tận [BUF04] trận\ntại [BUF03] sao?\pCậu đúng là một nguồn cảm hứng tuyệt vời!\nBai bai nhé!",
    "MC0164": r"Chào cậu! [BUF01] phải không?\nXin chào, [BUF02] đây nè!\lTôi vừa nghe được tin sốt dẻo rồi nhé!\pCậu đã trở thành quán quân tại\n[BUF03] tận [BUF04] lần cơ đấy?\pThật là đỉnh cao! Tôi cũng phải phấn đấu làm tốt hơn mới được!\nHẹn gặp lại nhé!",
    "MC0165": r"Chào cậu, [BUF02] đây nè!\nTôi vừa nghe chuyện về cậu đấy!\pNgười ta bảo cậu đã giành được [BUF04] danh hiệu vô địch\ntại [BUF03].\pTuyệt đỉnh quá đi thôi! Không biết liệu tôi có thể trở thành một nhà vô địch được không nhỉ?",
    "MC0166": r"Chào [BUF01] nhé!\nTôi là [BUF02] đây nè.\lDạo này cậu thế nào rồi?\pTôi nghe nói cậu đã vô địch giải đấu [BUF04] lần tại [BUF03] đấy!\pLần tới nhớ nâng con số đó lên thêm một lần nữa nhé!\nHẹn sớm gặp lại cậu!",
    "MC0167": r"Chào [BUF01][BUF05].\n[BUF02] đây.\pTôi nghe nói cậu đã trở thành nhà vô địch\ntại [BUF03] tận [BUF04] lần rồi đấy.\pNghe là biết cậu đã nỗ lực chăm chỉ thế nào rồi.\nTôi cũng sẽ cố gắng đuổi kịp cậu!",
    "MC0168": r"Chào [BUF01][BUF05] nha!\nTôi là [BUF02] đây.\pTôi nghe nói cậu đã toàn thắng đoạt cúp [BUF04] lần tại [BUF03] đấy.\pTôi cũng phải bắt nhịp cố lên mới được!\nHẹn sớm gặp lại nhé!",
    "MC0169": r"Chào [BUF01][BUF05]?\n[BUF02] đây nè. Cậu khỏe chứ?\pNhân tiện, tôi nghe nói cậu đã đăng quang ngôi vô địch\n[BUF04] lần tại [BUF03] rồi đấy.\pTôi phải mau chóng huấn luyện thêm cho các Pokémon của mình\ntrước khi cậu bỏ tôi lại quá xa mới được.",
    "MC0170": r"[BUF01][BUF05] phải không?\n[BUF02] đây nè.\pCậu vừa ở [BUF03]\nvà đã trở thành quán quân [BUF04] lần sao?\pĐỉnh thật đấy. Nhân tiện, dạo này cậu có bắt được con Pokémon quý hiếm nào không?\pỒ, thật thế à.\nThôi nhé, tạm biệt.",
}
